Процедура ПриНачалеРаботыСистемы()
    МинутыЗаявки = 31;
    Если МинутыЗаявки < 0 Или МинутыЗаявки > 180 Тогда
        Статус = "Ошибка";
    ИначеЕсли МинутыЗаявки = 0 Тогда
        Статус = "Без затрат";
    ИначеЕсли МинутыЗаявки <= 30 Тогда
        Статус = "Срочно";
    Иначе
        Статус = "Обычно";
    КонецЕсли;
    Сообщить(Статус);
КонецПроцедуры
